BEGIN IMMEDIATE;
CREATE TABLE billing_policies(organization_id TEXT NOT NULL,tenant_id TEXT NOT NULL,project_id TEXT NOT NULL,agent_uid TEXT NOT NULL,digest TEXT NOT NULL CHECK(length(digest)=64),version TEXT NOT NULL,policy_json TEXT NOT NULL CHECK(length(policy_json)<=65536),actor_id TEXT NOT NULL,operation_id TEXT NOT NULL,created_at_ms INTEGER NOT NULL,PRIMARY KEY(organization_id,tenant_id,project_id,agent_uid,digest),UNIQUE(organization_id,tenant_id,project_id,agent_uid,version),UNIQUE(organization_id,tenant_id,project_id,agent_uid,actor_id,operation_id));
CREATE TABLE billing_current(organization_id TEXT NOT NULL,tenant_id TEXT NOT NULL,project_id TEXT NOT NULL,agent_uid TEXT NOT NULL,digest TEXT NOT NULL,PRIMARY KEY(organization_id,tenant_id,project_id,agent_uid),FOREIGN KEY(organization_id,tenant_id,project_id,agent_uid,digest) REFERENCES billing_policies(organization_id,tenant_id,project_id,agent_uid,digest));
CREATE TABLE billing_accounts(organization_id TEXT NOT NULL,tenant_id TEXT NOT NULL,budget_key TEXT NOT NULL,window_start_ms INTEGER NOT NULL,window_end_ms INTEGER NOT NULL,currency TEXT NOT NULL,hard_micros INTEGER NOT NULL CHECK(hard_micros>=0),soft_micros INTEGER NOT NULL CHECK(soft_micros>=0 AND soft_micros<=hard_micros),reserved_micros INTEGER NOT NULL CHECK(reserved_micros>=0),consumed_micros INTEGER NOT NULL CHECK(consumed_micros>=0),revision INTEGER NOT NULL CHECK(revision>=0),PRIMARY KEY(organization_id,tenant_id,budget_key,window_start_ms));
CREATE TABLE billing_run_reservations(organization_id TEXT NOT NULL,tenant_id TEXT NOT NULL,project_id TEXT NOT NULL,agent_uid TEXT NOT NULL,run_id TEXT NOT NULL REFERENCES runs(id),budget_key TEXT NOT NULL,window_start_ms INTEGER NOT NULL,reserved_micros INTEGER NOT NULL CHECK(reserved_micros>=0),policy_digest TEXT NOT NULL,state TEXT NOT NULL CHECK(state IN ('reserved','settled')),charged_micros INTEGER CHECK(charged_micros>=0),PRIMARY KEY(organization_id,tenant_id,project_id,agent_uid,run_id,budget_key));
CREATE TABLE billing_run_limits(run_id TEXT PRIMARY KEY REFERENCES runs(id),provider_attempts INTEGER NOT NULL CHECK(provider_attempts>=0),input_upper_bound INTEGER NOT NULL CHECK(input_upper_bound>=0),sandbox_allocated_ms INTEGER NOT NULL CHECK(sandbox_allocated_ms>=0));
CREATE TABLE billing_sandbox_allocations(run_id TEXT NOT NULL REFERENCES runs(id),operation_id TEXT NOT NULL,wall_limit_ms INTEGER NOT NULL CHECK(wall_limit_ms>0),started_at_ms INTEGER NOT NULL,PRIMARY KEY(run_id,operation_id));
CREATE TABLE usage_charges(seq INTEGER PRIMARY KEY AUTOINCREMENT,organization_id TEXT NOT NULL,tenant_id TEXT NOT NULL,project_id TEXT NOT NULL,agent_uid TEXT NOT NULL,run_id TEXT NOT NULL REFERENCES runs(id),operation_id TEXT NOT NULL,model TEXT,kind TEXT NOT NULL,owner_json TEXT NOT NULL CHECK(length(owner_json)<=4096),units_json TEXT NOT NULL CHECK(length(units_json)<=16384),policy_digest TEXT,currency TEXT,cost_micros INTEGER CHECK(cost_micros>=0),outcome_unknown INTEGER NOT NULL CHECK(outcome_unknown IN (0,1)),created_at_ms INTEGER NOT NULL,UNIQUE(organization_id,tenant_id,project_id,agent_uid,operation_id));
CREATE TRIGGER immutable_billing_policy_update BEFORE UPDATE ON billing_policies BEGIN SELECT RAISE(ABORT,'immutable billing policy'); END;
CREATE TRIGGER immutable_billing_policy_delete BEFORE DELETE ON billing_policies BEGIN SELECT RAISE(ABORT,'immutable billing policy'); END;
CREATE TRIGGER immutable_usage_update BEFORE UPDATE ON usage_charges BEGIN SELECT RAISE(ABORT,'immutable usage'); END;
CREATE TRIGGER immutable_usage_delete BEFORE DELETE ON usage_charges BEGIN SELECT RAISE(ABORT,'immutable usage'); END;
INSERT INTO schema_migrations VALUES(33,CAST(strftime('%s','now') AS INTEGER)*1000);
COMMIT;
